   *Precondition: This device ID has not been used before, and the selected contact is already a registered staff member in the airport organization.
   *Postcondition: A new Device is created with Id, Name, and Location, and its Contacts points to the chosen Staff. The device can then be searched and referenced consistently by its Id and location.*/
  createDevice(
    id: number,
    name: string,
    location: string,
    contactsid: number,
  ): boolean {
    /*Definition Start*/
    let contact: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: Staff) =>
            l({
              logic: () => s.Id === contactsid,
              description: "s.Id=contactsid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s:Staff|s.Id=contactsid)",
    }).build().pass;
    let existingDevice: Device = l({
      logic: () =>
        getRepository(Device).find(
          (d: Device) =>
            l({
              logic: () => d.Id === id,
              description: "d.Id=id",
            }).build().pass,
        ),
      description: "Device.allInstance()->any(d:Device|d.Id=id)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(existingDevice),
        description: "existingDevice.oclIsUndefined()",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(contact) === false,
          description: "contact.oclIsUndefined()=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

