  orderItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let item: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: any) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i|i.Barcode=barcode)",
    }).build().pass;
    let orderProduct: OrderProduct = l({
      logic: () =>
        getRepository(OrderProduct).find(
          (op: any) =>
            l({
              logic: () => op.Id === 1,
              description: "op.Id=1",
            }).build().pass,
        ),
      description: "OrderProduct.allInstance()->any(op|op.Id=1)",
    }).build().pass;
    let orderEntry: OrderEntry = l({
      logic: () =>
        getRepository(OrderEntry).find(
          (oe: any) =>
            l({
              logic: () => oe.Item === item,
              description: "oe.Item=item",
            }).build().pass,
        ),
      description: "OrderEntry.allInstance()->any(oe|oe.Item=item)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(item) === false,
